const j = $input.first().json;
let site = String(j.website || '').trim();
if (site && !/^https?:\/\//i.test(site)) site = 'https://' + site;
let origin = '';
try { origin = new URL(site).origin; } catch (e) { origin = site.replace(/\/+$/, ''); }
const split = s => [].concat(s || []).join('\n').split(/[\n,]+/).map(x => x.trim()).filter(Boolean);
const extra = split(j.extra_pages).map(u => /^https?:/i.test(u) ? u : origin + (u.startsWith('/') ? '' : '/') + u);
const pages = [...new Set([site || origin].concat(extra))].filter(Boolean).slice(0, 5);
const geo = { 'Egypt': 2818, 'Saudi Arabia': 2682, 'United Arab Emirates': 2784, 'Kuwait': 2414, 'Qatar': 2634, 'Jordan': 2400, 'United Kingdom': 2826, 'United States': 2840 };
const country = j.country || 'Egypt';
const searchLanguage = j.search_language || (j.language === 'English' ? 'English' : 'Arabic');
const cid = String(j.google_ads_customer_id || '').replace(/[^0-9]/g, '');
return [{ json: {
  mode: j.mode || 'form',
  website: site || origin, origin, pages,
  business: String(j.business || j.product || '').trim(),
  country, geo_id: geo[country] || null,
  search_language: searchLanguage, language_constant: searchLanguage === 'English' ? 1000 : 1019,
  keywords: split(j.keywords).slice(0, 20),
  competitors: split(j.competitors).slice(0, 5),
  google_ads_customer_id: cid,
  language: j.language === 'English' ? 'English' : 'Arabic'
} }];

const brief = $('Normalize SEO Brief').first().json;
const urls = $('Build Page List').all().map(i => i.json.url);
const host = (() => { try { return new URL(brief.origin).hostname.replace(/^www\./, ''); } catch (e) { return ''; } })();
function strip(s) { return String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim(); }
function attrs(tag) { const o = {}; const re = /([\w:-]+)\s*=\s*("([^"]*)"|'([^']*)')/g; let m; while ((m = re.exec(tag))) o[m[1].toLowerCase()] = m[3] != null ? m[3] : m[4]; return o; }
function tags(html, name) { return html.match(new RegExp('<' + name + '\\b[^>]*>', 'gi')) || []; }
function meta(html, key, val) { const t = tags(html, 'meta').map(attrs).find(a => String(a[key] || '').toLowerCase() === val); return t ? (t.content || '') : ''; }
function blocks(html, name) { const re = new RegExp('<' + name + '\\b[^>]*>([\\s\\S]*?)<\\/' + name + '>', 'gi'); const out = []; let m; while ((m = re.exec(html))) out.push(strip(m[1])); return out; }
const pages = $input.all().map((it, i) => {
  const j = it.json || {};
  const html = String(j.body != null ? j.body : (j.data != null ? j.data : ''));
  const url = urls[i] || '';
  if (!html || j.error) return { url, status: j.statusCode || 0, error: (j.error && (j.error.message || j.error)) || 'Could not fetch page' };
  const links = tags(html, 'link').map(attrs);
  const imgs = tags(html, 'img').map(attrs);
  const anchors = tags(html, 'a').map(attrs).map(a => a.href || '').filter(h => h && !/^(#|javascript:|mailto:|tel:)/i.test(h));
  let internal = 0, external = 0;
  anchors.forEach(h => { try { const u = new URL(h, url); (u.hostname.replace(/^www\./, '') === host ? internal++ : external++); } catch (e) {} });
  const schemas = [];
  const sre = /<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi; let sm;
  while ((sm = sre.exec(html))) { try { const o = JSON.parse(sm[1]); [].concat(o['@graph'] || o).forEach(x => x && x['@type'] && schemas.push([].concat(x['@type']).join('/'))); } catch (e) { schemas.push('invalid JSON-LD'); } }
  const text = strip(html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' '));
  const htmlTag = (html.match(/<html\b[^>]*>/i) || [''])[0];
  const title = (blocks(html, 'title')[0] || '');
  const desc = meta(html, 'name', 'description');
  const h1 = blocks(html, 'h1');
  const h2 = blocks(html, 'h2');
  const hdr = j.headers || {};
  return {
    url, status: j.statusCode || 200, https: /^https:/i.test(url),
    title, title_length: title.length,
    meta_description: desc, meta_description_length: desc.length,
    h1: h1.slice(0, 3), h1_count: h1.length, h2: h2.slice(0, 8), h2_count: h2.length,
    canonical: (links.find(l => String(l.rel || '').toLowerCase() === 'canonical') || {}).href || '',
    hreflang: links.filter(l => l.hreflang).map(l => l.hreflang + ' -> ' + l.href).slice(0, 10),
    robots_meta: meta(html, 'name', 'robots'), x_robots_tag: hdr['x-robots-tag'] || '',
    viewport: meta(html, 'name', 'viewport'),
    html_lang: attrs(htmlTag).lang || '', html_dir: attrs(htmlTag).dir || '',
    og_title: meta(html, 'property', 'og:title'), og_image: meta(html, 'property', 'og:image'), twitter_card: meta(html, 'name', 'twitter:card'),
    images: imgs.length, images_missing_alt: imgs.filter(a => !a.alt || !String(a.alt).trim()).length,
    internal_links: internal, external_links: external,
    schema_types: [...new Set(schemas)],
    word_count: text ? text.split(' ').length : 0,
    html_kb: Math.round(html.length / 1024),
    compression: hdr['content-encoding'] || 'none', cache_control: hdr['cache-control'] || ''
  };
});
return [{ json: { pages } }];

const brief = $('Normalize SEO Brief').first().json;
function first(name) { try { return $(name).first().json || {}; } catch (e) { return {}; } }
const pages = first('Audit On-Page SEO').pages || [];
const robots = first('Fetch robots.txt');
const robotsTxt = String(robots.body != null ? robots.body : (robots.data || ''));
const sm = first('Fetch sitemap.xml');
const smTxt = String(sm.body != null ? sm.body : (sm.data || ''));
const sitemap = { status: sm.statusCode || 0, url_count: (smTxt.match(/<loc>/gi) || []).length, is_index: /<sitemapindex/i.test(smTxt) };
const psi = first('PageSpeed Insights (mobile)');
const lr = psi.lighthouseResult || {};
const cat = lr.categories || {};
const au = lr.audits || {};
const le = (psi.loadingExperience && psi.loadingExperience.metrics) || {};
const score = k => cat[k] && cat[k].score != null ? Math.round(cat[k].score * 100) : null;
const pagespeed = psi.lighthouseResult ? {
  performance: score('performance'), seo: score('seo'), accessibility: score('accessibility'), best_practices: score('best-practices'),
  lcp: (au['largest-contentful-paint'] || {}).displayValue || '', cls: (au['cumulative-layout-shift'] || {}).displayValue || '',
  tbt: (au['total-blocking-time'] || {}).displayValue || '', fcp: (au['first-contentful-paint'] || {}).displayValue || '',
  field_inp_ms: (le.INTERACTION_TO_NEXT_PAINT || {}).percentile || null, field_lcp_ms: (le.LARGEST_CONTENTFUL_PAINT_MS || {}).percentile || null,
  top_opportunities: Object.values(au).filter(a => a && a.details && a.details.type === 'opportunity' && a.score != null && a.score < 0.9).slice(0, 6).map(a => a.title + (a.displayValue ? ' (' + a.displayValue + ')' : ''))
} : { error: (psi.error && (psi.error.message || psi.error)) || 'PageSpeed Insights not available' };
const kp = first('Keyword Planner Ideas');
const keyword_ideas = (kp.results || []).map(r => ({ keyword: r.text, volume: Number((r.keywordIdeaMetrics || {}).avgMonthlySearches) || 0, competition: (r.keywordIdeaMetrics || {}).competition || '', cpc_high: (r.keywordIdeaMetrics || {}).highTopOfPageBidMicros ? Math.round(Number(r.keywordIdeaMetrics.highTopOfPageBidMicros) / 10000) / 100 : null })).sort((a, b) => b.volume - a.volume).slice(0, 80);
const keyword_source = keyword_ideas.length ? 'Google Ads Keyword Planner' : (brief.google_ads_customer_id ? 'Keyword Planner failed: ' + JSON.stringify(kp.error || kp).slice(0, 300) : 'not connected - volumes are estimates');
const technical_facts = {
  robots_txt: { status: robots.statusCode || 0, has_sitemap_line: /sitemap:/i.test(robotsTxt), blocks_all: /disallow:\s*\/\s*$/im.test(robotsTxt), excerpt: robotsTxt.slice(0, 600) },
  sitemap, pagespeed
};
return [{ json: { ...brief, pages, technical_facts, keyword_ideas, keyword_source, data_for_ai: JSON.stringify({ pages, technical_facts, keyword_ideas }).slice(0, 50000) } }];

