function textOf(j) {
  if (!j) return '';
  if (typeof j.mergedResponse === 'string' && j.mergedResponse) return j.mergedResponse;
  const parts = (j.content && j.content.parts) || (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts);
  if (Array.isArray(parts)) return parts.map(p => p.text || '').join('');
  if (typeof j.text === 'string') return j.text;
  return JSON.stringify(j);
}
function parseJson(t) {
  const s = String(t || '').trim().replace(/^\s*\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60\s*$/, '');
  const a = s.indexOf('{'); const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return { parse_error: true, raw: String(t || '') };
}
const d = $('Compile SEO Data').first().json;
const r = parseJson(textOf($input.first().json));
const ar = d.language === 'Arabic';
const L = ar ? { title: 'تقرير الـ SEO', summary: 'الملخص', wins: 'مكاسب سريعة', kw: 'بحث الكلمات المفتاحية', onpage: 'تحسين الصفحات (On-page)', tech: 'الفحص التقني', speed: 'السرعة و Core Web Vitals (موبايل)', bl: 'فرص الباك لينك', content: 'خطة المحتوى', plan: 'خطة 30/60/90 يوم', comps: 'المنافسون', sources: 'المصادر', vol: 'بحث/شهر', diff: 'الصعوبة', issues: 'المشاكل', sugg: 'المقترح', facts: 'بيانات الصفحة' } : { title: 'SEO Report', summary: 'Summary', wins: 'Quick wins', kw: 'Keyword research', onpage: 'On-page optimisation', tech: 'Technical SEO checks', speed: 'Speed & Core Web Vitals (mobile)', bl: 'Backlink opportunities', content: 'Content plan', plan: '30/60/90-day plan', comps: 'Competitors', sources: 'Sources', vol: 'Searches/mo', diff: 'Difficulty', issues: 'Issues', sugg: 'Suggested', facts: 'Page facts' };
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function arr(v) { return Array.isArray(v) ? v : (v ? [v] : []); }
function list(a) { a = arr(a).filter(Boolean); return a.length ? '<ul>' + a.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '<p class="muted">-</p>'; }
function pill(s) { return '<span class="pill s-' + esc(String(s || '').toLowerCase()) + '">' + esc(s) + '</span>'; }
function link(u, t) { return u ? '<a href="' + esc(u) + '" target="_blank" rel="noopener">' + esc(t || u) + '</a>' : esc(t); }
const sc = Number(r.seo_score) || 0;
let h = '<section class="top"><div class="gauge" style="--v:' + sc + '"><b>' + sc + '</b><span>/100</span></div><div><h2>' + L.summary + '</h2><p>' + esc(r.executive_summary) + '</p>' + (r.parse_error ? '<pre>' + esc(r.raw) + '</pre>' : '') + '<h3>' + L.wins + '</h3>' + list(r.quick_wins) + '</div></section>';
const ps = (d.technical_facts || {}).pagespeed || {};
if (ps.performance != null) {
  h += '<section><h2>' + L.speed + '</h2><div class="kpis">' + [['Performance', ps.performance], ['SEO', ps.seo], ['Accessibility', ps.accessibility], ['Best practices', ps.best_practices]].map(k => '<div class="kpi"><span>' + k[0] + '</span><b class="' + (k[1] >= 90 ? 'good' : k[1] >= 50 ? 'mid' : 'bad') + '">' + esc(k[1]) + '</b></div>').join('') + '</div><div class="kpis">' + [['LCP', ps.lcp], ['CLS', ps.cls], ['TBT', ps.tbt], ['FCP', ps.fcp], ['INP (field)', ps.field_inp_ms ? ps.field_inp_ms + ' ms' : '-']].map(k => '<div class="kpi"><span>' + k[0] + '</span><b>' + esc(k[1] || '-') + '</b></div>').join('') + '</div>' + list(ps.top_opportunities) + '</section>';
}
h += '<section><h2>' + L.kw + '</h2><p class="muted">Volumes: ' + esc(d.keyword_source) + '</p>' + arr(r.keyword_clusters).map(c => '<div class="card"><h3>' + esc(c.cluster) + ' ' + pill(c.priority) + ' <small class="muted">' + esc(c.intent) + ' · ' + esc(c.target_page) + '</small></h3><div class="tbl"><table><thead><tr><th>Keyword</th><th>' + L.vol + '</th><th>' + L.diff + '</th></tr></thead><tbody>' + arr(c.keywords).map(k => '<tr><td>' + esc(k.keyword) + '</td><td>' + esc(k.monthly_volume) + (k.source === 'estimate' ? ' <small class="muted">(est.)</small>' : '') + '</td><td>' + pill(k.difficulty) + '</td></tr>').join('') + '</tbody></table></div></div>').join('') + '</section>';
const facts = {}; arr(d.pages).forEach(p => { facts[p.url] = p; });
h += '<section><h2>' + L.onpage + '</h2>' + arr(r.on_page).map(p => { const f = facts[p.url] || {}; return '<div class="card"><h3>' + link(p.url) + ' <span class="score">' + esc(p.score) + '/100</span></h3><div class="grid2"><div><b>' + L.issues + '</b><ul>' + arr(p.issues).map(i => '<li>' + pill(i.severity) + ' ' + esc(i.issue) + '<br><small class="muted">' + esc(i.fix) + '</small></li>').join('') + '</ul></div><div><b>' + L.sugg + '</b><p><small>Title</small><br>' + esc(p.suggested_title) + '</p><p><small>Meta description</small><br>' + esc(p.suggested_meta_description) + '</p><p><small>H1</small><br>' + esc(p.suggested_h1) + '</p><p><small>Keyword</small><br>' + esc(p.target_keyword) + '</p></div></div>' + (f.url ? '<details><summary>' + L.facts + '</summary><p class="muted">Title (' + f.title_length + '): ' + esc(f.title) + '<br>Meta (' + f.meta_description_length + '): ' + esc(f.meta_description) + '<br>H1 x' + f.h1_count + ': ' + esc(arr(f.h1).join(' | ')) + '<br>Words: ' + f.word_count + ' · Images: ' + f.images + ' (' + f.images_missing_alt + ' without alt) · Links: ' + f.internal_links + ' internal / ' + f.external_links + ' external<br>Canonical: ' + esc(f.canonical || '-') + ' · Schema: ' + esc(arr(f.schema_types).join(', ') || '-') + ' · lang=' + esc(f.html_lang || '-') + ' dir=' + esc(f.html_dir || '-') + '</p></details>' : '') + '</div>'; }).join('') + '</section>';
h += '<section><h2>' + L.tech + '</h2><div class="tbl"><table><tbody>' + arr(r.technical).map(t => '<tr><td>' + pill(t.status) + '</td><td><b>' + esc(t.check) + '</b><br><span class="muted">' + esc(t.details) + '</span></td><td>' + esc(t.fix) + '</td></tr>').join('') + '</tbody></table></div></section>';
h += '<section><h2>' + L.bl + '</h2><div class="cards">' + arr(r.backlinks).map(b => '<div class="card"><h4>' + link(b.url, b.site) + ' ' + pill(b.priority) + '</h4><span class="tag">' + esc(b.type) + '</span><p>' + esc(b.how_to) + '</p></div>').join('') + '</div></section>';
if (arr(r.competitors).length) h += '<section><h2>' + L.comps + '</h2><ul>' + arr(r.competitors).map(c => '<li><b>' + esc(c.domain) + '</b> - ' + esc(c.strengths) + '</li>').join('') + '</ul></section>';
h += '<section><h2>' + L.content + '</h2><div class="tbl"><table><tbody>' + arr(r.content_plan).map(c => '<tr><td><b>' + esc(c.title) + '</b><br><small class="muted">' + esc(c.reason) + '</small></td><td>' + esc(c.target_keyword) + '</td><td><span class="tag">' + esc(c.type) + '</span></td></tr>').join('') + '</tbody></table></div></section>';
const ap = r.action_plan || {};
h += '<section><h2>' + L.plan + '</h2><div class="grid3"><div><h3>0-30</h3>' + list(ap.days_0_30) + '</div><div><h3>31-60</h3>' + list(ap.days_31_60) + '</div><div><h3>61-90</h3>' + list(ap.days_61_90) + '</div></div></section>';
if (arr(r.sources).length) h += '<section><h2>' + L.sources + '</h2><ol>' + arr(r.sources).filter(s => s && s.url).map(s => '<li>' + link(s.url, s.title) + '</li>').join('') + '</ol></section>';
const css = ':root{--bg:#f6f7fb;--card:#fff;--ink:#1d2433;--muted:#667085;--line:#e4e7ec;--acc:#3b5bdb;--good:#12805c;--mid:#b54708;--bad:#c4320a}@media (prefers-color-scheme:dark){:root{--bg:#0f131a;--card:#171c26;--ink:#e6e9ef;--muted:#98a2b3;--line:#2a3140;--acc:#7c9cff;--good:#4cc38a;--mid:#fdb022;--bad:#ff8a65}}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 system-ui,-apple-system,Segoe UI,Tahoma,sans-serif}.wrap{max-width:1100px;margin:0 auto;padding:24px 16px}header{border-bottom:3px solid var(--acc);margin-bottom:16px;padding-bottom:10px}header h1{margin:0}section{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px;margin:16px 0}h2{color:var(--acc);margin:0 0 12px}.top{display:flex;gap:24px;align-items:flex-start;flex-wrap:wrap}.top>div:last-child{flex:1;min-width:260px}.gauge{width:130px;height:130px;border-radius:50%;background:conic-gradient(var(--acc) calc(var(--v)*1%),var(--line) 0);display:flex;align-items:center;justify-content:center;flex-direction:column;position:relative}.gauge::before{content:"";position:absolute;inset:12px;border-radius:50%;background:var(--card)}.gauge b,.gauge span{position:relative}.gauge b{font-size:34px}.card{border:1px solid var(--line);border-radius:10px;padding:14px;margin:10px 0}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px}.cards .card{margin:0}.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}.grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.kpis{display:flex;flex-wrap:wrap;gap:10px;margin:8px 0}.kpi{flex:1;min-width:120px;border:1px solid var(--line);border-radius:10px;padding:10px}.kpi span{display:block;font-size:12px;color:var(--muted)}.kpi b{font-size:20px}.good{color:var(--good)}.mid{color:var(--mid)}.bad{color:var(--bad)}.tbl{overflow-x:auto}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid var(--line);padding:8px;text-align:start;vertical-align:top}.pill{display:inline-block;border-radius:99px;padding:0 9px;font-size:12px;border:1px solid var(--line)}.s-pass,.s-low{background:var(--good);color:#fff;border-color:transparent}.s-warning,.s-medium{background:var(--mid);color:#fff;border-color:transparent}.s-fail,.s-high{background:var(--bad);color:#fff;border-color:transparent}.tag{border:1px solid var(--line);border-radius:99px;padding:0 9px;font-size:12px}.score{float:inline-end;color:var(--acc)}.muted{color:var(--muted)}a{color:var(--acc)}summary{cursor:pointer;color:var(--acc)}pre{white-space:pre-wrap}';
